__NUXT_JSONP__("/posts/building-meet-harvey-a-dive-into-wordpress-membership-plugin", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K,L,M,N,O,P,Q){return {data:[{post:{slug:z,description:u,title:"Building Meet Harvey:  a dive into Wordpress membership plugin",type:f,imgCover:z,tags:["wordpress",t,f],createdAt:"2019-10-11T00:00:00.000Z",toc:[{id:A,depth:l,text:B},{id:C,depth:l,text:D},{id:E,depth:l,text:F},{id:G,depth:l,text:H},{id:I,depth:l,text:J},{id:K,depth:l,text:L},{id:M,depth:l,text:v},{id:s,depth:l,text:N}],body:{type:O,children:[{type:b,tag:g,props:{},children:[{type:a,value:u}]},{type:a,value:c},{type:a,value:c},{type:b,tag:m,props:{id:A},children:[{type:b,tag:d,props:{href:"#intro",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:B}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"Those last months, I have set up a joint venture with a young ex-lawyer to build a personal development platform targeting french lawyers. The name is \"Meet Harvey\" (in reference to the tv serie “Suits\"). It aims to deliver high quality posts to help leveraging employed lawyers who want to get on their own business."}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"My role was to design a brand for the platform as well as develop the whole project."}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"During our discussions with my partner around what could be the best possible solution for this kind of project, we’ve come to realize that a membership site was what we needed."}]},{type:a,value:c},{type:b,tag:m,props:{id:C},children:[{type:b,tag:d,props:{href:"#stack",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:D}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"I’ve been experimenting a lot with single page application ecosystems for nearly a year now (especially Vue.js) and I first wanted to use it for this project. It’s quite heavy on the feature side this time: we need a CMS, an authentication system and protected contents for users,  a payment gateway and an invoice system."}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"At first I quickly tested a Jamstack configuration combining Nuxt.js + "},{type:b,tag:d,props:{href:"https:\u002F\u002Fstrapi.io\u002F",rel:[h,i,j],target:k},children:[{type:a,value:"Strapi CMS"}]},{type:a,value:" + Stripe following this well explained "},{type:b,tag:d,props:{href:"https:\u002F\u002Fmedium.com\u002Fstrapi\u002Fcooking-a-deliveroo-clone-with-nuxt-vue-js-graphql-strapi-and-stripe-ebeb49320993",rel:[h,i,j],target:k},children:[{type:a,value:"tutorial"}]},{type:a,value:". But I struggled a lot (especially with Strapi that remains too buggy at this time). Considering the project has a low budget, tight deadline, and is very features-demanding, I've chosen to use a common Wordpress + a membership plugin solution."}]},{type:a,value:c},{type:b,tag:m,props:{id:E},children:[{type:b,tag:d,props:{href:"#web-design",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:F}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"The starting point of the project was first to create an iconic animated scene that will take place on the homepage hero. I used a rotating divided plate that shows different micro-scene in a sequential way, built with Cinema 4D as usual. See here in action."}]},{type:a,value:c},{type:b,tag:m,props:{id:G},children:[{type:b,tag:d,props:{href:"#team-workflow",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:H}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"We use Trello as our project management tool, I used it a lot in the past with Gandi.net, it remains a very efficient tool with a neat interface."}]},{type:a,value:c},{type:b,tag:m,props:{id:I},children:[{type:b,tag:d,props:{href:"#wordpress-setup",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:J}]},{type:a,value:c},{type:b,tag:w,props:{},children:[{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"As the work on templates was barely finished, I setup a few very useful plugins that I didn’t know before:"}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Ffr.wordpress.org\u002Fplugins\u002Fautoptimize\u002F",rel:[h,i,j],target:k},children:[{type:a,value:"Auto-optimize"}]},{type:a,value:": it's now my go-tool for global assets optimisation and bundling, it rocketed the Lighthouse score in a breeze"}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fsuperpwa.com\u002F",rel:[h,i,j],target:k},children:[{type:a,value:"Super PWA"}]},{type:a,value:": it setup automatically the whole site to comply with the progressive web app requirements. I consider PWA as a best practice we should tend to, in order to build a more resilient web."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:m,props:{id:K},children:[{type:b,tag:d,props:{href:"#mailchimp-integration",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:L}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"The first goal is engaging people in a free mail sequence. Some well positioned call-to-actions trigger a form deployment with an email input field. These forms are plugged with a "},{type:b,tag:d,props:{href:"https:\u002F\u002Fmailchimp.com\u002F",rel:[h,i,j],target:k},children:[{type:a,value:"Mailchimp"}]},{type:a,value:" subscription flow through a Contact-form-7 integration. I found it quite simple though a bunch of others solutions exist as well. Mailchimp seems to be a very powerful tool but I find their UX very confusing."}]},{type:a,value:c},{type:b,tag:m,props:{id:M},children:[{type:b,tag:d,props:{href:"#memberpress",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:v}]},{type:a,value:c},{type:b,tag:w,props:{},children:[{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"The second goal is engaging people in a membership to access protected contents from the site that will be delivered on a regular basis."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"We chose to go with "},{type:b,tag:d,props:{href:"https:\u002F\u002Fmemberpress.com\u002F",rel:[h,i,j],target:k},children:[{type:a,value:v}]},{type:a,value:" as our membership plugin. This is the most common and reliable solution in the Wordpress membership plugin galaxy. It takes place with a lot of features in the WP admin. There is an extensive doc that help with configuring, but I found things are not always straightforward. It was tedious to figure out what was the right template to use to apply custom styles for exemple. There is is a lot of fields that can overwrite the base configuration and it takes time to get used to this management system."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"A big drawback is the lack of official traduction (the site is in French), so I hopefully found a translation file in a "},{type:b,tag:d,props:{href:"https:\u002F\u002Fgithub.com\u002Fwp-premium\u002Fmemberpress-basic\u002Fblob\u002Fmaster\u002Fi18n\u002Fmemberpress-fr_FR.po",rel:[h,i,j],target:k},children:[{type:a,value:"Github repo"}]},{type:a,value:"."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Another drawback is an incomplete drip system for protected content : it’s impossible to setup a sequence. We have to setup a rule instead for every single content with staggered drip time."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"On the positive side, the payment gateway is very easy to implement, we went with Stripe and we can easily test the workflow."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"To conclude on Memberpress, it fits pretty well with our project but there’s a lack of clarity in some configuration panels and the way it’s organized."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:m,props:{id:s},children:[{type:b,tag:d,props:{href:"#next",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:N}]},{type:a,value:c},{type:b,tag:w,props:{},children:[{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"The project has just been launched in its initial phase, that is to said, without the membership part. It is available on "},{type:b,tag:d,props:{href:"https:\u002F\u002Fmeetharvey.co",rel:[h,i,j],target:k},children:[{type:a,value:"meetharvey.co"}]},{type:a,value:". The second phase will be launched within the next coming weeks."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Aside from the goal of helping people to develop themselves on specifics topics, we expect to get a side-income as well. It’s the first time I take part in such a project, and chances to achieve this will greatly depends on the marketing actions, which I’m not in charge of. My part will be to maintain a reliable system that performs all user expectations."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I’m thinking about testing a solution that I’ve heard of thousand of times through podcasts : "},{type:b,tag:d,props:{href:"https:\u002F\u002Fsentry.io\u002F",rel:[h,i,j],target:k},children:[{type:a,value:"sentry.io"}]},{type:a,value:". It’s a tool to monitor activity and track errors. More on this on a future post if its implementation is relevant or not..."}]},{type:a,value:c}]}]},excerpt:{type:O,children:[{type:b,tag:g,props:{},children:[{type:a,value:u}]}]},dir:"\u002Fposts",path:"\u002Fposts\u002Fbuilding-meet-harvey-a-dive-into-wordpress-membership-plugin",extension:".md",updatedAt:"2025-10-10T15:29:17.521Z"},relatedPosts:[{title:"Giskard Hub: behind the LLMs evaluation platform",type:f,imgCover:"the-giskard-hub",tags:[s,x,y,t,"fastApi",P,f],createdAt:"2026-03-16T00:00:00.000Z",path:"\u002Fposts\u002Fthe-giskard-hub"},{title:"Red Teamer: Building a Button-Based AI Chatbot Game",type:f,imgCover:"red-teamer-building-a-button-based-ai-chatbot-game",tags:["game",s,Q,x,y,t,"cinema 4D",P,f],createdAt:"2025-09-07T00:00:00.000Z",path:"\u002Fposts\u002Fred-teamer-building-a-button-based-ai-chatbot-game"},{title:"Explainer Motion Design Journey",type:f,imgCover:"explainer-motion-design-journey",tags:["motion graphics","after effects","video",f],createdAt:"2025-06-07T00:00:00.000Z",path:"\u002Fposts\u002Fexplainer-motion-design-journey"},{title:"Building a narrative game with Next.js and AI",type:f,imgCover:"building-a-narrative-game-with-nextjs-and-ai",tags:["games",s,Q,x,y,t,"dzine",f],createdAt:"2025-03-20T00:00:00.000Z",path:"\u002Fposts\u002Fbuilding-a-narrative-game-whith-nextjs-and-ai"}]}],fetch:[{counter:3},{counter:32},{counter:72}],mutations:[]}}("text","element","\n","a","li","article","p","nofollow","noopener","noreferrer","_blank",2,"h2","true",-1,"span","icon","icon-link","next","devs","This post tells the path I've been through to setup a full Wordpress membership site with protected content.","Memberpress","ul","Tailwind","Figma","building-meet-harvey-a-dive-into-wordpress-membership-plugin","intro","Intro","stack","Stack","web-design","Web Design","team-workflow","Team workflow","wordpress-setup","Wordpress setup","mailchimp-integration","Mailchimp integration","memberpress","Next","root","AI","framer-motion")));